// 70% 확률로 실행, 30%는 SKIP
const run = Math.random() < 0.7;

if (!run) {
  console.log('[SKIP] 이번 사이클 건너뜀');
  return [{ json: { skipped: true, message: 'Skipped by random decision' } }];
}

// 카테고리 랜덤 선택 (이미 Python 스크립트가 처리)
return [{ json: { skipped: false, mode: 'once', timestamp: new Date().toISOString() } }];

const output = $json.stdout;

// 출력값이 있으면 JSON 파싱 시도
if (output) {
  try {
    // stdout에서 JSON 부분 찾기
    const lines = output.split('\n');
    let jsonStr = '';
    let inJson = false;
    for (const line of lines) {
      if (line.trim().startsWith('{')) {
        inJson = true;
      }
      if (inJson) {
        jsonStr += line + '\n';
      }
    }

    if (jsonStr) {
      const parsed = JSON.parse(jsonStr);

      const categories = parsed.categories_run || [];
      const duration = parsed.duration_seconds || 0;

      return [{
        json: {
          status: parsed.status || 'unknown',
          categories: categories.join(', '),
          count: categories.length,
          duration: `${duration}초`,
          timestamp: parsed.timestamp,
        }
      }];
    }
  } catch (e) {
    // JSON 파싱 실패해도 로그는 남김
  }
}

return [{ json: { status: 'completed', note: 'See exit code for details', exitCode: $json.exitCode } }];
